import { useEffect, useState } from 'react'
import type { TrackDefinition } from './types'

// Track files are generated by tools/TrackBuilder and named by Natsoft track code (e.g. MOUN.json).
// They're loaded on demand so adding circuits doesn't grow the main bundle.
const loaders = import.meta.glob<{ default: TrackDefinition }>('./*.json')

export function hasTrack(code: string): boolean {
  return `./${code}.json` in loaders
}

/** Loads the track for a Natsoft track code. Returns null while loading or if there's no file. */
export function useTrack(code: string | undefined): TrackDefinition | null {
  const [track, setTrack] = useState<TrackDefinition | null>(null)
  useEffect(() => {
    setTrack(null)
    const load = code ? loaders[`./${code}.json`] : undefined
    if (!load) return
    let cancelled = false
    load().then((m) => !cancelled && setTrack(m.default))
    return () => {
      cancelled = true
    }
  }, [code])
  return track
}
